477	function parseThresholds(thresholdStrings: string[] | undefined): Record<string, number> | undefined {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return undefined;
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	  for (const str of thresholdStrings) {
484	    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
485	    if (!match) {
486	      log.error(`Malformed threshold: "${str}". Expected format: <metric>=<number> (e.g., exact_match=0.9)`);
487	      process.exit(2);
488	    }
489	    const metricId = match[1];
490	    const minValue = Number.parseFloat(match[2]);
491	    if (Number.isNaN(minValue) || minValue < 0 || minValue > 1) {
492	      log.error(`Invalid threshold minimum for ${metricId}: must be a number between 0 and 1, got ${match[2]}`);
493	      process.exit(2);
494	    }
495	    thresholds[metricId] = minValue;
496	  }
497	  return thresholds;
498	}
