527	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
528	    evaluations,
529	    outputsPath: dataset.outputsPath,
530	    referencesPath: dataset.referencesPath,
531	    thresholds
532	  });
533	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
534	    report,
535	    format: options.format ?? 'json',
536	    reportPath: options.report
537	  });
538	  log.success('Evaluation report generated.', { path: resolvedPath });
539	
540	  if (report.passed === false) {
541	    process.exit(1);
542	  }
543	}
